var lead = (data.lead_minutes || 15) * 60000;
var baselineSpan = (data.baseline_minutes || 60) * 60000;

// Prefer an explicit override (manual runs on a past incident), then the
// triggering event's start, then now.
var raw = data.override || data.starts_at || '';
var anchor = raw ? new Date(raw) : new Date();
if (isNaN(anchor.getTime())) { anchor = new Date(); }

var now = new Date();
var incidentStart = new Date(anchor.getTime() - lead);
// Cap the tail so a manual run against an old incident does not scan for days.
var incidentEnd = new Date(Math.min(now.getTime(), anchor.getTime() + 30 * 60000));
var baselineStart = new Date(incidentStart.getTime() - baselineSpan);

function iso(d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); }
({
  anchor: iso(anchor),
  incident_start: iso(incidentStart),
  incident_end: iso(incidentEnd),
  baseline_start: iso(baselineStart),
  baseline_end: iso(incidentStart),
  searched: 'incident ' + iso(incidentStart) + ' to ' + iso(incidentEnd) +
            ' (anchor ' + iso(anchor) + ' minus ' + (lead / 60000) + 'm lead), ' +
            'baseline ' + iso(baselineStart) + ' to ' + iso(incidentStart)
})

function rows(x) { return (x && x.logs) ? x.logs : []; }
function key(r) {
  var l = r.labels || {};
  return (l.severity || '?') + ' ' + (l.sqlstate || 'no-sqlstate');
}
function count(r) { return parseInt((r.labels || {}).occurrences || '0', 10) || 0; }

// A collection task that FAILED has no output at all, which reaches this
// script as an empty string and yields zero rows — indistinguishable from a
// window that genuinely contained no errors. Successful queries always carry a
// metadata block, so its presence is the proof that the query actually ran.
//
// This is not hypothetical: CloudWatch hard-rejects (MalformedQueryException)
// any window ending before the log group was created, so on a freshly-shipped
// host the baseline query fails outright and every error would otherwise be
// reported as brand new.
function ran(x) { return !!(x && x.metadata); }
var baselineRan = ran(data.baseline_patterns);

var incident = rows(data.incident_patterns);
var baseline = rows(data.baseline_patterns);
var errorRows = rows(data.errors);
var connRows = rows(data.connection_events);

var base = {};
baseline.forEach(function (r) { base[key(r)] = count(r); });

var isNew = [], elevated = [], persistent = [], unclassified = [];
incident.forEach(function (r) {
  var k = key(r), c = count(r), b = base[k] || 0;
  var entry = { pattern: k, incident_count: c, baseline_count: b };
  if (!baselineRan) { unclassified.push(entry); }
  else if (b === 0) { isNew.push(entry); }
  else if (c > b) { elevated.push(entry); }
  else { persistent.push(entry); }
});
isNew.sort(function (a, b2) { return b2.incident_count - a.incident_count; });
elevated.sort(function (a, b2) { return b2.incident_count - a.incident_count; });

var md = data.metadata || {};
({
  window: data.searched || '',
  // Row counts make "no errors" provably different from "the query never ran".
  collected: {
    errors: errorRows.length,
    incident_patterns: incident.length,
    baseline_patterns: baseline.length,
    connection_events: connRows.length
  },
  queries_ran: {
    errors: ran(data.errors),
    incident_patterns: ran(data.incident_patterns),
    baseline_patterns: baselineRan,
    connection_events: ran(data.connection_events)
  },
  baseline_available: baselineRan,
  unclassified_patterns: unclassified,
  new_patterns: isNew,
  elevated_patterns: elevated,
  persistent_patterns: persistent,
  verdict: !baselineRan
      ? (incident.length > 0
          ? ('warning: ' + incident.length + ' error class(es) in the incident window, but the '
             + 'baseline query did not run, so whether they are new is unknown')
          : 'info: no errors in the incident window; baseline query did not run')
      : isNew.length > 0
      ? ('critical: ' + isNew.length + ' error class(es) appear only during the incident')
      : (elevated.length > 0
          ? ('warning: ' + elevated.length + ' error class(es) elevated versus baseline')
          : (errorRows.length > 0
              ? 'info: errors present but unchanged from baseline'
              : 'info: no errors logged in the incident window')),
  sample_errors: errorRows.slice(0, 15).map(function (r) {
    return { time: r.timestamp || '', message: r.message || '' };
  }),
  connection_failures: connRows.slice(0, 10).map(function (r) {
    return { time: r.timestamp || '', message: r.message || '' };
  })
})

